<template><div class="space-y-3 p-4"><h1 class="text-xl font-bold text-slate-800">Messages</h1><NuxtLink v-for="item in items" :key="item.id" :to="item.commerce_order_id ? `/messages/${item.commerce_order_id}` : `/buyer/requests/${item.procurement_request_id}`" class="m-card block"><p class="text-sm font-semibold text-slate-800">{{ item.subject }}</p><p class="mt-1 text-xs text-slate-400">{{ item.status }}</p></NuxtLink><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({ middleware: ['auth'] }); const { listThreads } = useCommerce(); const items = ref<any[]>([]); const error = ref(''); onMounted(async () => { try { items.value = (await listThreads()).items } catch (e: any) { error.value = e?.data?.detail || e?.message } })</script>
